// spec: specs/recommendations-similar-businesses.md (1.4) · кейс: .qa/tests/recommendations-similar-businesses/SIMILAR-04.md
// Две роли одновременно (гость и user, сессия ../auth/user.json) — каждая в своём окне через asUser.
// Прод, только просмотр: не-GET запросы блокируются в обоих окнах.
import { test, expect } from '../../fixtures';
import { Page } from '@playwright/test';
import { blockWrites, openListing, cardIds, viewedCategories, readCatalog, pickRoute, expectOrder } from './similar.helpers';

async function prepare(page: Page) {
  await blockWrites(page);
  await page.goto('/');
  // История категорий пуста перед маршрутом (сессия user могла её содержать).
  await page.evaluate(() => localStorage.removeItem('b4s_viewed_categories'));
}

test('Вошедший пользователь видит ту же выдачу, что гость, на том же маршруте #02706d @desktop @prod-safe', async ({ asUser }) => {
  const guest = await asUser('guest');
  const user = await asUser('user');
  await Promise.all([prepare(guest), prepare(user)]);

  await expect(guest.getByText('התחברות').first(), 'гость не вошёл').toBeVisible();
  await expect(user.locator('header').getByText('התחברות'), 'user вошёл').toHaveCount(0);

  const catalog = await readCatalog(guest);
  const route = pickRoute(catalog);
  for (const biz of route) await Promise.all([openListing(guest, biz.id), openListing(user, biz.id)]);
  const [a, b, c] = route;

  const expected = [c.category, b.category, a.category];
  expect(await viewedCategories(guest), 'история гостя').toEqual(expected);
  expect(await viewedCategories(user), 'история user — та же').toEqual(expected);

  const guestCards = await cardIds(guest);
  expectOrder(catalog, c, expected as string[], guestCards);
  expect(await cardIds(user), 'карточки и порядок у user = у гостя').toEqual(guestCards);
});
